const statusLabels={missing:'Fehlt',placeholder:'Platzhalter',brief:'Noch knapp',invalid:'Ungültige Angabe',present:'Angabe vorhanden',optional:'Optional'};
function completeness(d,tasks=[]){return elements.map(([key,label,step,action,minWords,optional])=>{
 const value=key==='_schedule'?(tasks.length?'Arbeitsphasen vorhanden':''):text(d,key);
 let status=!value?(optional?'optional':'missing'):'present';
 if(value&&/^(?:[-–—?.…]+|n[/.]?a[.]?|tbd|todo|test|xxx|offen|folgt|später|noch (?:offen|zu ergänzen|keine?\b.*)|wird (?:ergänzt|nachgetragen)|platzhalter(?:.*)|beispiel(?:.*))$/i.test(value))status='placeholder';
 if(value&&status==='present'&&minWords&&value.split(/\s+/).length<minWords)status='brief';
 if(value&&['start','deadline'].includes(key)){const t=Date.parse(value+'T00:00:00Z');if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(t)||new Date(t).toISOString().slice(0,10)!==value)status='invalid'}
 if(value&&key==='hours'&&(!Number.isFinite(Number(value))||Number(value)<=0||Number(value)>168))status='invalid';
 return {key,label,step,action,optional:!!optional,status,statusLabel:statusLabels[status],value,minWords};
})}
