  const messages={missing:'Dazu ist noch keine Angabe erfasst.',placeholder:'Das Feld enthält einen Platzhalter statt einer ausgearbeiteten Angabe.',brief:`Der Eintrag umfasst weniger als ${x.minWords} Wörter. Das ist nur ein Hinweis zur Ausarbeitung, kein Qualitätsurteil.`,invalid:'Die Angabe hat kein gültiges Format oder liegt ausserhalb des sinnvollen Wertebereichs.'};
