 for(const [id,pattern,title]of [['outline-method',/method|vorgehen|untersuchungsdesign/i,'Methodenabschnitt'],['outline-results',/ergebnis|auswertung|analyse|befund/i,'Ergebnis- oder Analyseabschnitt'],['outline-conclusion',/fazit|schluss|beantwortung/i,'Fazit mit Beantwortung der Frage']])if(!pattern.test(text(d,'outline')))component(id,'outline',title+' nicht erkennbar','Der Abschnitt ist in der Gliederung nicht ausdrücklich erkennbar; eine andere Benennung kann passend sein.','Prüfe die Gliederung und ergänze den Abschnitt oder eine klar erkennbare entsprechende Überschrift.');
 const paragraphs=['motivation','goal','procedure','analysis','claim','warrant','alternatives'];
 for(const k of paragraphs){const sentences=text(d,k).split(/(?<=[.!?])\s+/);const long=sentences.find(s=>s.split(/\s+/).length>38);if(long)add('long-'+k,'Präzision und Lesbarkeit','Langen Gedankenschritt aufteilen','Ein Satz umfasst mehr als 38 Wörter.','Trenne Behauptung, Begründung und Schlussfolgerung, ohne den Zusammenhang zu verlieren. Verknüpfungswörter allein belegen keine Logik.',[k],true)}
